function stepStatusBind(res,e)
{
    var statusCurrentStep = 0;
    for(var i = 0;i<res.length;i++)
    {
      if(res[i].taskStatus==5)
      {
        statusCurrentStep++;
      }
    }
    let stepStatus = e.getWidgetRef('stepStatus',false);
    stepStatus.setActiveStep(statusCurrentStep);
}

